const b = $json.body;
const isReviewComment = !b.issue && !!b.pull_request;
const prNumber = isReviewComment ? b.pull_request.number : b.issue.number;
const commentBody = (b.comment && b.comment.body) || '';
return [{ json: {
  isReviewComment,
  prNumber,
  commentId: b.comment && b.comment.id,
  commentBody,
  commentUrl: (b.comment && b.comment.html_url) || '',
  path: (b.comment && b.comment.path) || null,
  line: (b.comment && (b.comment.line || b.comment.original_line)) || null,
  diffHunk: (b.comment && b.comment.diff_hunk) || null,
  repoOwner: b.repository.owner.login,
  repoName: b.repository.name,
  repoFull: b.repository.full_name,
  senderLogin: b.sender && b.sender.login
}}];

const pr = $json;
const prev = $('Normalize').item.json;
const map = JSON.parse($env.N8N_AGENT_MAP || '{}');
const prAuthor = pr.user && pr.user.login;
const commentBody = (prev.commentBody || '').trim();
const commandUsers = ($env.N8N_COMMAND_USERS || '').split(',').map(s => s.trim()).filter(Boolean);
const agentLogins = Object.keys(map);
let mentionedLogin = null;
let instruction = commentBody;
if (commandUsers.includes(prev.senderLogin) && agentLogins.length) {
  const re = new RegExp('@(' + agentLogins.join('|') + ')(?![a-z0-9-])', 'i');
  const m = commentBody.match(re);
  if (m) {
    mentionedLogin = agentLogins.find(l => l.toLowerCase() === m[1].toLowerCase());
    instruction = (commentBody.slice(0, m.index) + commentBody.slice(m.index + m[0].length)).trim();
  }
}
const hasFixSlash = /^\/fix\b/i.test(commentBody);
const authorIsAgent = !!map[prAuthor];
// Author-agent fallback (no explicit @-mention, no /fix) only applies to
// inline review comments — those are almost always actionable feedback on
// code. General PR-thread comments (issue_comment) are human conversation
// and must not silently trigger the PR-author agent.
const targetLogin = mentionedLogin
  || (authorIsAgent && prev.isReviewComment ? prAuthor
      : (hasFixSlash ? $env.N8N_IMPLEMENTER_DEFAULT : null));
if (!targetLogin) {
  return [];
}
const entry = map[targetLogin];
if (!entry) {
  throw new Error(`N8N_AGENT_MAP missing agent "${targetLogin}"`);
}
return [{ json: {
  ...prev,
  branch: pr.head.ref,
  baseRef: pr.base.ref,
  headSha: pr.head.sha,
  prAuthor,
  host: entry.host,
  sshPort: entry.port,
  sshUser: entry.user,
  implementerLogin: targetLogin,
  instructionMode: mentionedLogin ? 'mention' : (hasFixSlash ? 'fix-slash' : 'author-agent'),
  instruction,
}}];

const j = $input.first().json;
const location = j.path ? ` at ${j.path}${j.line ? ':' + j.line : ''}` : '';
const diffBlock = j.diffHunk ? `\n\nRelevant diff hunk:\n\`\`\`diff\n${j.diffHunk}\n\`\`\`\n` : '';
let prompt;
if (j.instructionMode === 'mention') {
  prompt = `You are @${j.implementerLogin}, responding to an instruction from @${j.senderLogin} on PR #${j.prNumber}, branch ${j.branch}.

Instruction${location}:
---
${j.instruction}
---${diffBlock}

Follow the instruction exactly. Keep the change minimal and scoped to what was asked. Commit with message: "address comment ${j.commentId} from @${j.senderLogin}". Do not rebase. Do not push — the workflow handles push.
`;
} else {
  prompt = `You are addressing review feedback on PR #${j.prNumber}, branch ${j.branch}.

Reviewer comment${location}:
---
${j.commentBody}
---${diffBlock}

Make the smallest change that addresses the comment. If the comment is a question, answer it inline by committing a clarifying code comment — never just echo back. Commit with message:
"address review comment ${j.commentId}". Do not rebase. Do not push — the workflow handles push.
`;
}
return [{ json: { ...j, promptB64: Buffer.from(prompt, 'utf8').toString('base64') } }];
